from admissions_records import *
record('kaist',[route(label=L('KAIST international undergraduate admission, Daejeon','KAIST: международный бакалаврский приём, Daejeon'),applicability=cycle(L('2027 admissions guide','Руководство приёма 2027'),[2027]),english={'requirement':'required-unless-exempt','ielts':{'accepted':True,'min':None,'recommended':6.5},'toefl':{'accepted':True,'scales':[{'period':'pre2026','recommended':83},{'period':'post2026','recommended':4.5}]},'alternatives':L('TOEIC 720 and TEPS 326 are also recommended scores. A language report is required unless exempt, but the numerical table is explicitly recommended. DET, ITP and home/online tests are not accepted.','TOEIC 720 и TEPS 326 также рекомендуемые. Без освобождения языковой результат обязателен, но числовая таблица прямо рекомендательная. DET, ITP и домашние/онлайн-тесты не принимаются.'),'waiver':L('Listed English-speaking nationalities are exempt; an English-medium high-school certificate or official letter is another exemption route.','Перечисленные англоязычные гражданства освобождены; сертификат или официальное письмо школы об английском языке обучения — другой маршрут освобождения.')},academic={'satPolicy':'required-alternatives','note':L('At least one official SAT, ACT, AP, IB, GCE A-level or national school-leaving/university-entrance examination is required. Predicted IB/A-level can lead to conditional admission pending final results.','Обязателен хотя бы один официальный SAT, ACT, AP, IB, GCE A-level либо национальный выпускной/вступительный экзамен. Предварительные IB/A-level могут дать условный приём до окончательных результатов.')},note=L('The guide identifies English as the official language of instruction for international students and says most courses are English; confirm remaining programme-specific course requirements.','Руководство называет английский официальным языком преподавания иностранцам и указывает большинство курсов на английском; оставшиеся требования конкретной программы нужно уточнить.'),sources=[S('https://admission.kaist.ac.kr/wz/api/common/files/view/intl-undergraduate/pdf/Admissions_Guide_for_2027_admission.pdf',L('KAIST 2027 international undergraduate guide','KAIST: международное руководство бакалавриата 2027'),pages=[3,6,7,8,9],access='pdf-read')])],'Separated compulsory academic alternatives and language-report submission from recommended English numbers.', ['IELTS variant/sections, exact degree-specific course language and individual national-exam qualification remain unconfirmed.'])

record('unist',[route(label=L('UNIST Fall 2027 international bachelor admission, Ulsan','UNIST: международный бакалаврский приём Fall 2027, Ulsan'),language='unknown',applicability={'label':'Fall 2027','entryYears':[2027],'status':'confirmed','intakes':['fall-2027']},english={'requirement':'required-unless-exempt','ielts':{'accepted':True,'min':None},'toefl':{'accepted':True},'alternatives':L('The complete 2027 guide requires TOEFL, IELTS, TEPS or TOEIC evidence, valid within two years of the application deadline, but does not publish numerical thresholds. A missing published number is not a confirmed zero minimum.','Полное руководство 2027 требует TOEFL, IELTS, TEPS либо TOEIC моложе двух лет к сроку заявки, но не публикует числовых порогов. Отсутствие опубликованной цифры не означает подтверждённый нулевой минимум.'),'waiver':L('Applicants from the US, Canada, UK, Australia, New Zealand and Ireland are exempt in this guide. A general school-MOI exemption is not stated.','В руководстве освобождены кандидаты из США, Канады, Великобритании, Австралии, Новой Зеландии и Ирландии. Общее освобождение по школьному MOI не указано.')},academic={'satPolicy':'optional','note':L('SAT/ACT/IB/A-level are in the supplementary document list, separately from required language evidence. TOPIK is supplementary too.','SAT/ACT/IB/A-level включены в дополнительные документы, отдельно от обязательного языкового подтверждения. TOPIK также дополнительный.')},documents=[L('Application/study plan, school diploma and recent transcripts, identity/family evidence; authenticated originals after registration. Scholarship and non-scholarship admission tracks are distinct.','Заявка/учебный план, школьный диплом и недавние оценки, гражданство/родство; заверенные оригиналы после регистрации. Стипендиальный и несубсидируемый маршруты приёма различаются.')],sources=[S('https://admu-intl.unist.ac.kr/admission-eng/admissions/admissions.do?articleNo=306812&attachNo=591437&mode=download',L('UNIST Fall 2027 full international undergraduate guide','UNIST: полное международное руководство бакалавриата Fall 2027'),pages=[2,3,4,5,6,7,8],access='pdf-read')])],'Established the actual 2027 required language tests and optional academic evidence without inventing an IELTS cutoff.', ['The read guide does not establish numerical English thresholds, IELTS variant/sections, school-MOI exemption or the exact teaching-language mix of each degree.'])

knu='https://home.knu.ac.kr/HOME/global/sub.htm?nav_code=glo1549935033'
ks=[S(knu,L('Kyungpook current international undergraduate eligibility','Kyungpook: актуальный международный бакалаврский допуск'),access='web-html-read')]
record('kyungpook-national-university',[route(id='general-eligibility',label=L('International first-year general eligibility — major conditions remain','Общий международный допуск первокурсника — условия специальности сохраняются'),language='unknown',english={'requirement':'alternative-to-local-language','ielts':{'accepted':True,'variant':'IELTS Academic','min':5.5},'toefl':{'accepted':True,'scales':[{'period':'legacy','min':59}]},'alternatives':L('General eligibility accepts English evidence OR Korean alternatives: CEFR B2, New TEPS 202; or TOPIK 3, university Korean course level 3, specified KIIP or overseas King Sejong Intermediate 1. This does not establish a wholly English degree.','Общий допуск принимает английское подтверждение ИЛИ корейские альтернативы: CEFR B2, New TEPS 202; либо TOPIK 3, университетский корейский уровня 3, указанный KIIP либо зарубежный King Sejong Intermediate 1. Это не подтверждает полностью английскую степень.')},academic={'satPolicy':'unknown'},note=L('The page publishes a Fall 2027 schedule but says the semester-specific department guide will be announced in March. General language rules are not therefore confirmed for every Fall 2027 major.','Страница публикует расписание Fall 2027, но сообщает, что руководство специальностей семестра выйдет в марте. Общие языковые правила поэтому не подтверждены для каждой специальности Fall 2027.'),sources=ks),route(id='korean-computing',label=L('Computer Science and Engineering — Korean qualification exception','Computer Science and Engineering — исключение по корейскому'),language='ko',programmeIds=['computer-science'],localLanguage=[{'name':'TOPIK','requirement':L('Level 4 or higher for Computer Science and Engineering; Media and Communication separately requires level 5.','Уровень 4 и выше для Computer Science and Engineering; Media and Communication отдельно требует уровень 5.'),'note':L('The general IELTS 5.5 alternative does not remove these named departmental requirements. Verify the semester guide before applying.','Общая альтернатива IELTS 5,5 не отменяет названных условий подразделения. Перед подачей нужно руководство конкретного семестра.')}],academic={'satPolicy':'unknown'},sources=ks)],'Separated general English/Korean eligibility alternatives from named TOPIK departmental exceptions and future guide publication.', ['Fall 2027 department guide, exact programme language, IELTS sections/new TOEFL scale and academic SAT/ACT policy remain unconfirmed.'])
finish()
